mapper.select:
select pro.P_Name as pName, pro.P_Code as pCode, pro.P_Approve_Budget as pApproveBudget, c1.C_Name as tcBuildName, c2.C_Name as tcDesignName, c3.C_Name as tcConstructionName, mn.* from Technical_Check mn left join Pre_Project pro on pro.P_Id = mn.P_Id left join SYS_Company c1 on c1.C_Id=mn.Tc_Build_Id left join SYS_Company c2 on c2.C_Id=mn.Tc_Design_Id left join SYS_Company c3 on c3.C_Id=mn.Tc_Construction_Id ${params.authSql}
and mn.state=#{params.state}
and mn.p_Id=#{params.pId}
and likePname(#{params.pName},mn.P_Id)=true
and INSTR(pro.P_Name,#{params.pName})
and INSTR(pro.P_Code,#{params.pCode})
and INSTR(mn.Create_Uname,#{params.createUname})
and likeCname(#{params.tcBuildName},mn.Tc_Build_Id)=true
and INSTR(c1.C_Name,#{params.tcBuildName})
and likeCname(#{params.tcDesignName},mn.Tc_Design_Id)=true
and INSTR(c2.C_Name,#{params.tcDesignName})
and likeCname(#{params.tcConstructionName},mn.Tc_Construction_Id)=true
and INSTR(c3.C_Name,#{params.tcConstructionName})
order by mn.${params.sortFiled} ${params.sortType}
order by ${params.sortSideFiled} ${params.sortType}
order by mn.Create_Time desc
